/* Real EuroSAT imagery + the trainable CNN; generated scenery never enters training. */
const Vision={
 data:null,loading:null,openToken:0,net:null,worker:null,trainingJob:null,busy:false,id:16,filter:0,page:0,sampleId:null,kernel:'vertical',scanX:10,scanY:10,scanned:new Set(),channel:0,brightness:1,shift:0,flipped:false,probeCount:0,finalResult:null,finalCount:0,note:'',error:null,
 saved:read('academy-vision-v4',{selected:[],history:[],augment:false,trainedIds:'',model:null,baseline:null,metrics:null,finalCount:0}),
 async open(id){const token=++this.openToken;this.completionId=id;this.exported=false;this.id=id===30?20:id;this.note='';this.error=null;this.probeCount=0;this.probeChanges=new Set();this.scanned=new Set();this.brightness=1;this.shift=0;this.flipped=false;
  if(!this.data){shell(missionHeading(id,'ORBITAL VISION','正在载入真实遥感图像…')+'<div class="loading-state"><span class="loading-ring"></span><p>首次进入时下载图像与像素数据，后续任务复用。</p></div>');try{if(!this.loading)this.loading=this.loadData().finally(()=>{this.loading=null});const data=await this.loading;if(token!==this.openToken||missionMode!=='vision')return;this.data=data}catch(e){if(token===this.openToken&&missionMode==='vision'){shell(missionHeading(id,'ORBITAL VISION','图像尚未载入')+`<div class="mission-feedback">${esc(e.message)}<button class="primary" onclick="Vision.open(${id})">重试</button></div>`)}return}}
  if(token!==this.openToken||missionMode!=='vision')return;
  if(!this.net){try{this.net=new TinyCNN(this.saved.model)}catch(e){this.saved.model=null;this.net=new TinyCNN();this.note='旧模型记录无法读取，已初始化新模型。'}}
  if(!this.sampleId)this.sampleId=this.pool('development')[0].id;this.finalCount=this.saved.finalCount||0;this.render();
 },
 async loadData(){let controller=typeof AbortController!=='undefined'?new AbortController():null,timer=setTimeout(()=>controller?.abort(),15000);try{let r=await fetch('assets/eurosat/dataset-u8.json?v=5',controller?{signal:controller.signal}:{});if(!r.ok)throw Error('图像下载失败，请重试');let data=await r.json();if(!Array.isArray(data.samples)||data.samples.length!==300||data.samples.some(s=>!s.id||!['train','development','final'].includes(s.split)||![0,1,2].includes(s.label)||s.rgb8?.length!==1728))throw Error('图像数据不完整，请重新下载');return data}catch(e){throw Error(e.name==='AbortError'?'图像下载超时，请检查网络后重试':e.message)}finally{clearTimeout(timer)}},
 pool(split){return this.data.samples.filter(s=>s.split===split)},
 names:['森林','水域','居民区'],
 image(s){return 'assets/eurosat/'+s.image},
 sample(){return this.data.samples.find(s=>s.id===this.sampleId)||this.pool('development')[0]},
 picked(){let set=new Set(this.saved.selected);return this.pool('train').filter(s=>set.has(s.id))},
 counts(){return [0,1,2].map(c=>this.picked().filter(s=>s.label===c).length)},
 store(){persist('academy-vision-v4',this.saved)},
 ids(){return this.saved.selected.slice().sort().join('|')},
 dirty(){return this.saved.trainedIds!==this.ids()},
 toggle(id){if(this.busy)return;this.finalResult=null;if(this.saved.selected.includes(id))this.saved.selected=this.saved.selected.filter(x=>x!==id);else if(this.saved.selected.length<90)this.saved.selected.push(id);else {this.note='本次实验最多选 90 张；可以移除重复或不合适的样本。'}this.store();this.render()},
 starter(){if(this.busy)return;this.finalResult=null;this.saved.selected=[0,1,2].flatMap(c=>this.pool('train').filter(s=>s.label===c).slice(0,12).map(s=>s.id));this.store();this.note='已选取每类 12 张，共 36 张起步样本。你可以逐张检查、移除或增加。';this.render()},
 source(){modal('图像来源与实验范围',`<div class="explain"><h3>EuroSAT / Sentinel-2</h3><p>本章使用真实的 RGB 遥感影像。森林、水域和居民区，每类 60 张训练候选、20 张开发样本、20 张最终评估样本。</p><p>标签来自原始数据集，不由课堂模型生成。缩略图保留 64×64 像素；CNN 输入缩小为 24×24 RGB。输入值缩放到 −1～1。</p><p>三组不共享同一张原图。这是图像层面的划分，不能据此证明模型能泛化到新的地理区域。图块没有提供可用于本课拼接的坐标，观测板不是连续地理地图。</p><a href="https://github.com/phelber/EuroSAT" target="_blank" rel="noopener noreferrer">原始项目与数据说明 ↗</a><p class="microcopy">EuroSAT: Patrick Helber, Benjamin Bischke, Andreas Dengel, Damian Borth. Contains modified Copernicus Sentinel data. 本课将 RGB 影像缩小用于教学。</p><p><a href="assets/eurosat/LICENSE-EuroSAT.txt" target="_blank" rel="noopener">MIT 许可与署名</a></p></div>`)},
 chooseSample(id){this.sampleId=id;this.render()},
 inspectKernel(k){this.kernel=k;this.scanned.add(k);this.render()},
 setAug(v){this.saved.augment=v;this.store();this.render()},
 train(){
  if(this.busy||!this.data||!this.net)return;
  if(this.counts().some(n=>n<6)){this.note='先为每类选至少 6 张训练图像，或使用“每类 12 张起步”。';this.render();return}
  if(this.dirty()){this.net=new TinyCNN();this.saved.model=null;this.saved.history=[];this.saved.baseline=null;this.saved.metrics=null;this.saved.augmentedEpochs=0;this.saved.trainedIds=''}
  const job={ids:this.ids(),augment:this.saved.augment,train:this.picked(),dev:this.pool('development'),epochs:12,completed:0,total:12,mode:'worker',timer:null,startTimer:null};
  this.trainingJob=job;this.busy=true;this.finalResult=null;this.exported=false;this.note='正在启动训练。完成的轮次会自动保存，可以随时停止。';this.render();
  if(typeof Worker==='undefined'){this.startLocal(job);return}
  try{
   const worker=new Worker('cnn-worker.js?v=5');this.worker=worker;
   worker.onmessage=e=>{if(this.trainingJob===job&&this.worker===worker)this.receiveTraining(job,e.data)};
   worker.onerror=e=>{e.preventDefault?.();if(this.trainingJob!==job||this.worker!==worker)return;if(!job.completed)this.startLocal(job);else this.failTraining('后台任务中断，已保留完成的轮次。可点击继续训练。')};
   job.startTimer=setTimeout(()=>{if(this.trainingJob===job&&job.mode==='worker'&&!job.started)this.startLocal(job)},8000);
   worker.postMessage({type:'train',model:this.net.export(),train:job.train,dev:job.dev,epochs:12,lr:.002,augment:job.augment});
  }catch(e){this.startLocal(job)}
 },
 receiveTraining(job,d){
  if(this.trainingJob!==job)return;
  clearTimeout(job.startTimer);job.started=true;
  if(d.type==='baseline'){if(!this.saved.baseline)this.saved.baseline=d.metrics}
  if(d.type==='epoch'){
   this.net=new TinyCNN(d.model);this.saved.model=d.model;this.saved.trainedIds=job.ids;this.saved.metrics=d.metrics;
   this.saved.history.push({epoch:d.epoch,loss:d.loss,accuracy:d.metrics.accuracy});this.saved.history=this.saved.history.slice(-80);
   this.saved.augmentedEpochs=(this.saved.augmentedEpochs||0)+(job.augment?1:0);job.completed++;
   this.store();this.note=`本次训练 ${job.completed} / 12 轮 · 累计 ${d.epoch} 轮 · 开发集准确率 ${Math.round(d.metrics.accuracy*100)}% · 训练损失 ${d.loss.toFixed(3)}`;
   if(missionMode==='vision')this.render();
  }
  if(d.type==='done'){this.stop();this.note='训练完成。现在可以比较结果或继续训练；每一轮都是真实参数更新。';if(missionMode==='vision')this.render()}
  if(d.type==='error')this.failTraining('训练中断：'+d.message+'。已保留最近完成的轮次。');
 },
 startLocal(job){
  if(this.trainingJob!==job)return;
  if(this.worker)this.worker.terminate();this.worker=null;clearTimeout(job.startTimer);job.mode='local';job.started=true;
  // The exact same optimizer, yielded after each minibatch to keep controls responsive.
  const net=new TinyCNN(this.net.export());let batches=null;
  this.note='已切换到兼容训练模式。仍在本机更新同一个 CNN；可以停止并保留已完成的轮次。';this.render();
  const tick=()=>{if(this.trainingJob!==job)return;try{
   if(!job.baselineSent){job.baselineSent=true;this.receiveTraining(job,{type:'baseline',metrics:net.evaluate(job.dev)})}
   if(!batches)batches=net.epochBatches(job.train,{lr:.002,augment:job.augment});
   const step=batches.next();
   if(step.done){this.receiveTraining(job,{type:'epoch',epoch:net.epochs,loss:step.value,metrics:net.evaluate(job.dev),model:net.export()});batches=null;
    if(job.completed>=job.total){this.receiveTraining(job,{type:'done'});return}}
   if(this.trainingJob===job)job.timer=setTimeout(tick,0);
  }catch(e){this.failTraining('本机训练中断：'+e.message)}};
  job.timer=setTimeout(tick,0);
 },
 failTraining(message){this.stop();this.note=message;if(missionMode==='vision')this.render()},
 stop(){this.openToken++;const job=this.trainingJob;if(job){clearTimeout(job.timer);clearTimeout(job.startTimer)}this.trainingJob=null;if(this.worker)this.worker.terminate();this.worker=null;this.busy=false;if(this.net)this.saved.model=this.net.export();this.store()},
 reset(){if(this.busy)this.stop();this.net=new TinyCNN();this.saved.model=null;this.saved.history=[];this.saved.metrics=null;this.saved.baseline=null;this.saved.augmentedEpochs=0;this.saved.trainedIds='';this.finalResult=null;this.note='已重置模型参数，保留所选数据。';this.store();this.render()},
 transform(k,v){if(k==='brightness')this.brightness=+v;if(k==='shift')this.shift=+v;if(k==='flip')this.flipped=!this.flipped;this.probeChanges??=new Set();if(k==='brightness'&&this.brightness!==1||k==='shift'&&this.shift!==0||k==='flip'&&this.flipped)this.probeChanges.add(k);this.probeCount=this.probeChanges.size;this.updateProbe()},
 transformed(){return TinyCNN.transform(TinyCNN.input(this.sample()),this.brightness,this.shift,this.flipped)},
 probeHTML(){let s=this.sample(),base=this.net.forward(TinyCNN.input(s)),t=this.net.forward(this.transformed());return `<div class="comparison-pred"><div><small>原始图像</small><strong>${this.names[base.label]}</strong></div><span>→</span><div class="${t.label===s.label?'good-text':'warn-text'}"><small>变换之后</small><strong>${this.names[t.label]}</strong></div></div><p>参考标签：${this.names[s.label]} · ${t.label===s.label?'当前变换下预测正确。继续比较不同图像。':'发现错误。检查图像是否仍然保留足够的类别信息。'}</p><div class="score-bars">${Array.from(t.probs,(p,i)=>`<div><span>${this.names[i]}</span><i style="width:${p*100}%"></i><b>${(p*100).toFixed(1)}%</b></div>`).join('')}</div><small>这里显示 softmax 分数，未经可信度校准。</small>`},
 updateProbe(){let el=$('#probe-result');if(el)el.innerHTML=this.probeHTML();let val=$('#brightness-value');if(val)val.textContent=this.brightness.toFixed(2);let shift=$('#shift-value');if(shift)shift.textContent=this.shift;this.drawImages();this.updateComplete()},
 evaluate(){if(this.busy||!this.net.epochs||this.dirty())return;this.finalResult=this.net.evaluate(this.pool('final'));this.finalCount++;this.saved.finalCount=this.finalCount;this.store();this.note=this.finalCount===1?'最终评估已完成。此后如果根据结果继续调参，这组图像就不能再算未见过的独立验收。':'这是重复评估，分数只作学习参考。真实项目还需要另一组未参与调参的测试数据。';this.render()},
 export(){if(!this.net.epochs)return;let out={format:'ai-academy-cnn-v1',dataset:'EuroSAT subset',selected:this.saved.selected,model:this.net.export(),augment:this.saved.augment,history:this.saved.history,development:this.saved.metrics,final:this.finalResult};downloadJSON(out,'my-vision-model.json');this.exported=true;this.note='已导出模型权重、样本编号与评估记录。当前实验也已自动保存在本浏览器。';this.render()},
 remaining(){if(this.id===16)return this.names.map((name,c)=>`${name}：已选 ${this.counts()[c]} / 至少 6 张`);if(this.id===17)return [`比较至少两种滤镜（${Math.min(2,this.scanned.size)}/2）`];if(this.id===18)return [`当前模型至少训练 5 轮（${Math.min(5,this.net.epochs)}/5）`,this.dirty()?'数据有变动，请用当前数据重新训练':'✓ 模型与当前样本一致'];if(this.id===19)return [`尝试至少两种不同变换（${Math.min(2,this.probeCount)}/2）`,`开启数据增强并训练至少 5 轮（${Math.min(5,this.saved.augmentedEpochs||0)}/5）`,this.dirty()?'数据有变动，请重新训练':'✓ 当前样本一致'];return [this.finalResult?'✓ 当前模型已评估':'先训练，再运行保留图像评估',...(this.completionId===30?[this.exported?'✓ 作品已导出':'评估后点击“导出模型与实验记录”']:[])]},
 ready(){if(this.busy)return false;if(this.id===16)return this.counts().every(n=>n>=6);if(this.id===17)return this.scanned.size>=2;if(this.id===18)return this.net?.epochs>=5&&!this.dirty();if(this.id===19)return this.probeCount>=2&&(this.saved.augmentedEpochs||0)>=5&&!this.dirty();return !!this.finalResult&&!this.dirty()&&(this.completionId!==30||this.exported)},
 finish(){if(!this.ready())return;finishMission(this.completionId||this.id,['你选择的训练图像决定模型能参考哪些视觉经验。','卷积在局部图像上计算响应；不同滤镜回应不同变化。','卷积核和分类层都通过实际梯度更新学习。','你检验了变换下的表现，并用增强样本继续训练。',`已评估 ${this.finalResult?.n} 张保留图像，准确率 ${Math.round((this.finalResult?.accuracy||0)*100)}%。通关表示完成实验流程，不代表达到生产系统标准。`][this.id-16])},
 updateComplete(){let checklist=$('#vision-requirements');if(checklist)checklist.innerHTML='<strong>本关完成条件</strong>'+this.remaining().map(t=>`<span>${t}</span>`).join('');let b=$('#vision-complete');if(b)b.disabled=!this.ready()||this.busy},
 stats(){let m=this.saved.metrics,b=this.saved.baseline;return `<div class="training-stats"><div><small>实际训练轮数</small><strong>${this.net.epochs}</strong></div><div><small>训练前开发集</small><strong>${b?Math.round(b.accuracy*100)+'%':'—'}</strong></div><div><small>当前开发集</small><strong>${m?Math.round(m.accuracy*100)+'%':'—'}</strong></div></div>`},
 trainControls(){return `${this.busy?`<div class="training-progress" role="status"><strong>${this.trainingJob?.mode==='local'?'兼容模式 · 本机分批训练':'后台训练'} · ${this.trainingJob?.completed||0} / 12 轮</strong><progress max="12" value="${this.trainingJob?.completed||0}"></progress><small>完成一轮后更新分数并保存。停止会保留已完成的轮次。</small></div>`:''}${this.counts().some(n=>n<6)?'<p class="mission-feedback">每类至少需要 6 张训练图像。<button class="inline-link" onclick="Vision.starter()">选取每类 12 张起步样本 →</button></p>':''}<div class="training-actions"><button class="primary" ${this.busy?'disabled':''} onclick="Vision.train()">${this.net.epochs&&!this.dirty()?'继续训练 12 轮':'训练 CNN · 12 轮'}</button>${this.busy?'<button class="secondary" onclick="Vision.stop();Vision.render()">停止并保留进度</button>':'<button class="secondary" onclick="Vision.reset()">重置模型</button>'}</div>${this.dirty()&&this.net.epochs?'<p class="warn-text">训练数据已改变。下次训练将重新初始化模型，避免把旧样本的影响混入比较。</p>':''}`},
 render(){if(missionMode!=='vision'||!this.data||!this.net)return;let id=this.id,desc=['检查真实卫星图像，为每类选择至少 6 张训练样本。','在真实图像上移动扫描框，比较两种滤镜的响应。','训练一个真正的小型 CNN，比较训练前后的开发集表现。','改变光照与位置，寻找失败条件，再用数据增强改进。','用保留图像检验模型，逐张检查结果，并导出你的作品。'][id-16];let body=missionHeading(this.completionId||id,'ORBITAL VISION / SENTINEL-2',desc);
  body+=`<div class="vision-tabs">${[16,17,18,19,20].map((n,i)=>`<button class="${n===id?'active':''}" onclick="openLevel(${n})">${String(i+1).padStart(2,'0')} ${['采集','卷积','训练','挑战','验收'][i]}</button>`).join('')}</div>`;
  if(id===16){let candidates=this.pool('train').filter(s=>s.label===this.filter),shown=candidates.slice(this.page*12,this.page*12+12);body+=`<div class="collection-banner"><div><span class="eyebrow">DATA IS EVIDENCE</span><h2>一张图片，一次地表观测。</h2><p>模型看到的是 RGB 像素，参考答案来自原始数据集。检查不同纹理和拍摄条件，选出你要交给模型的经验。</p></div><div class="sample-stack">${[0,1,2].map(c=>`<img src="${this.image(this.pool('train').find(s=>s.label===c))}" alt="${this.names[c]}的真实卫星影像">`).join('')}</div></div><div class="collection-bar"><div class="choice-chips">${this.names.map((n,c)=>`<button class="${this.filter===c?'picked':''}" onclick="Vision.filter=${c};Vision.page=0;Vision.render()">${n} ${this.counts()[c]} 张</button>`).join('')}</div><button class="secondary" onclick="Vision.starter()">每类 12 张起步</button></div><div class="photo-grid">${shown.map(s=>`<button class="photo-card ${this.saved.selected.includes(s.id)?'selected':''}" onclick="Vision.toggle('${s.id}')"><img src="${this.image(s)}" alt="${this.names[s.label]} ${s.id}" loading="lazy"><span>${this.names[s.label]}<b>${this.saved.selected.includes(s.id)?'✓ 已选':'＋ 收集'}</b></span><small>${s.id}</small></button>`).join('')}</div><div class="pager"><button class="secondary" ${this.page===0?'disabled':''} onclick="Vision.page--;Vision.render()">上一组</button><span>${this.page+1} / ${Math.ceil(candidates.length/12)} · 已选 ${this.saved.selected.length} / 90</span><button class="secondary" ${this.page>=4?'disabled':''} onclick="Vision.page++;Vision.render()">下一组</button></div><div class="data-contract"><div><span>INPUT</span><h3>24 × 24 × 3</h3><p>每个位置的红、绿、蓝数值</p></div><div><span>TARGET</span><h3>地表类别</h3><p>森林 / 水域 / 居民区</p></div><div><span>QUESTION</span><h3>这张新图是什么？</h3><p>模型依据所选样本学习这个映射</p></div></div>`}
  else if(id===17){body+=`<div class="vision-workbench"><section class="operation-panel"><div class="panel-title"><span>LOCAL RESPONSE</span><h3>在画面上移动取样框</h3></div><div class="image-comparison"><div><canvas id="conv-photo" width="288" height="288" aria-label="可拖动的原始影像"></canvas><small>真实原图 / 输入缩小为 24×24</small></div><div><canvas id="conv-map" width="288" height="288" aria-label="实际计算的滤镜响应"></canvas><small>亮度越高，响应绝对值越大</small></div></div><div class="choice-chips">${[['vertical','左右差异'],['horizontal','上下差异'],['blur','局部平均']].map(([k,n])=>`<button class="${this.kernel===k?'picked':''}" onclick="Vision.inspectKernel('${k}')">${n}</button>`).join('')}</div><div id="kernel-number" class="mission-feedback"></div><p class="microcopy">这里的滤镜由人设定。下一关的 CNN 会从数据中学习 8 个卷积核。</p></section><aside class="evidence-panel">${this.samplePicker()}<div class="data-contract compact"><div><h3>同一个核，遍历画面</h3><p>每次取 3×3 邻域，逐项相乘后求和。移动扫描框，数值会随图像内容变化。</p></div></div></aside></div>`}
  else if(id===18){body+=`<div class="cnn-topology"><span>24×24 RGB</span><i>→</i><span>8 个可学习卷积核</span><i>→</i><span>ReLU + 平均池化</span><i>→</i><span>24 个隐藏单元</span><i>→</i><span>3 类输出</span></div><div class="vision-workbench"><section class="operation-panel"><div class="panel-title"><span>TRAIN THE VISION SYSTEM</span><h3>让错误推动参数更新</h3></div>${this.stats()}<canvas id="loss-chart" width="640" height="220" aria-label="实际训练损失曲线"></canvas>${this.trainControls()}<p>已选 ${this.saved.selected.length} 张训练图像。<button class="inline-link" onclick="openLevel(16)">检查训练集 ↗</button></p><p class="microcopy">所有卷积核与分类层参数从随机值开始，用交叉熵与 Adam 更新。开发集不参与梯度计算。</p></section><aside class="evidence-panel"><div class="panel-title"><span>INSPECT THE MODEL</span><h3>当前网络怎样响应？</h3></div><canvas id="feature-input" width="192" height="192" aria-label="当前输入图像"></canvas><div class="feature-grid">${Array.from({length:8},(_,i)=>`<div><canvas id="feature-${i}" width="88" height="88" aria-label="卷积通道 ${i+1}"></canvas><small>通道 ${i+1}</small></div>`).join('')}</div><p class="microcopy">显示当前模型的真实激活。一个通道不一定对应“树”或“房屋”等人类概念。</p>${this.samplePicker()}</aside></div>`}
  else if(id===19){body+=`<div class="vision-workbench"><section class="operation-panel"><div class="panel-title"><span>CHALLENGE THE MODEL</span><h3>图像变了，判断还可靠吗？</h3></div><div class="image-comparison"><div><canvas id="probe-before" width="240" height="240" aria-label="原始开发图像"></canvas><small>原始观测</small></div><div><canvas id="probe-after" width="240" height="240" aria-label="变换后的图像"></canvas><small>变换后的观测</small></div></div><label class="dark-slider">亮度 <b id="brightness-value">${this.brightness.toFixed(2)}</b><input type="range" min=".55" max="1.45" step=".05" value="${this.brightness}" oninput="Vision.transform('brightness',this.value)"></label><label class="dark-slider">水平位移 <b id="shift-value">${this.shift}</b> 像素<input type="range" min="-4" max="4" step="1" value="${this.shift}" oninput="Vision.transform('shift',this.value)"></label><button class="secondary" onclick="Vision.transform('flip',0)">水平翻转</button><div id="probe-result">${this.probeHTML()}</div></section><aside class="evidence-panel">${this.samplePicker()}<div class="panel-title"><span>REPAIR THROUGH EXPERIENCE</span><h3>扩大训练条件的覆盖</h3></div><p>在训练中加入轻微亮度变化、平移与水平翻转，再观察同样的变换。</p><label class="toggle-row"><input type="checkbox" ${this.saved.augment?'checked':''} ${this.busy?'disabled':''} onchange="Vision.setAug(this.checked)"> 开启数据增强</label>${this.trainControls()}${this.stats()}<p class="microcopy">只对训练样本增强。若变换已抹去关键信息，就不能期待模型仍可靠识别。</p></aside></div>`}
  else {let r=this.finalResult;body+=`<div class="review-intro"><div><span class="eyebrow">INDEPENDENT IMAGE CHECK</span><h2>把模型交给未参与训练的图像。</h2><p>60 张保留影像，每类 20 张。检查每类表现，不只看一个总分。</p></div><button class="primary" ${!this.net.epochs||this.busy||this.dirty()?'disabled':''} onclick="Vision.evaluate()">${this.finalCount?'再次评估（学习参考）':'运行保留图像评估'} →</button></div>${!this.net.epochs||this.dirty()?'<div class="mission-feedback">先在训练关完成当前数据集的模型训练。<button class="inline-link" onclick="openLevel(18)">去训练 →</button></div>':''}${r?`<div class="training-stats"><div><small>保留集准确率</small><strong>${Math.round(r.accuracy*100)}%</strong></div>${r.matrix.map((row,i)=>`<div><small>${this.names[i]} 召回率</small><strong>${Math.round(row[i]/row.reduce((a,b)=>a+b,0)*100)}%</strong></div>`).join('')}</div><div class="panel-title"><span>OBSERVATION BOARD</span><h3>逐张审阅模型的判断</h3><p>以下是独立图像的观测板，并非连续地理地图。描边标出错误。</p></div><div class="evaluation-grid">${r.items.map(item=>{let s=this.data.samples.find(s=>s.id===item.id);return `<button class="evaluation-tile ${item.pred===item.actual?'correct':'incorrect'}" onclick="Vision.review('${item.id}')"><img src="${this.image(s)}" alt="${this.names[item.actual]}，预测为${this.names[item.pred]}" loading="lazy"><span>${this.names[item.pred]} ${item.pred===item.actual?'✓':'×'}</span></button>`}).join('')}</div><button class="secondary" onclick="Vision.export()">导出模型与实验记录 ↓</button>`:'<div class="sealed-set"><span>FINAL SET / 60 IMAGES</span><h3>这组图像尚未参与本次训练</h3><p>先冻结你的数据与模型，再打开最终评估。</p></div>'}`}
  body+=`<div class="requirements-panel" id="vision-requirements"><strong>本关完成条件</strong>${this.remaining().map(t=>`<span>${t}</span>`).join('')}</div><div class="mission-feedback" role="status">${esc(this.note||'影像来自 EuroSAT；训练、特征图和分数均在此设备上实际计算。模型与样本选择会自动保存在本浏览器。')}</div><div class="mission-footer"><button class="secondary" onclick="Vision.source()">图像来源与数据划分</button><button id="vision-complete" class="primary" ${this.ready()&&!this.busy?'':'disabled'} onclick="Vision.finish()">${this.completionId===30&&!this.exported?'评估后导出作品，完成毕业任务':'完成实验，查看现实用途 →'}</button></div>`;shell(body);this.drawImages();this.bindScan();
 },
 samplePicker(){return `<div class="panel-title"><span>DEVELOPMENT IMAGES</span><h3>换一张观测</h3></div><div class="sample-picker">${[0,1,2].flatMap(c=>this.pool('development').filter(s=>s.label===c).slice(0,4)).map(s=>`<button class="${s.id===this.sampleId?'selected':''}" onclick="Vision.chooseSample('${s.id}')"><img src="${this.image(s)}" alt="${this.names[s.label]}"><span>${this.names[s.label]}</span></button>`).join('')}</div>`},
 drawRGB(id,x){let can=$('#'+id);if(!can)return;let ctx=can.getContext('2d'),scale=can.width/24;for(let y=0;y<24;y++)for(let col=0;col<24;col++){let i=(y*24+col)*3;ctx.fillStyle=`rgb(${[0,1,2].map(c=>Math.round((x[i+c]+1)*127.5)).join(',')})`;ctx.fillRect(col*scale,y*scale,scale+.2,scale+.2)}},
 drawImages(){if(!this.net||!this.data)return;let x=TinyCNN.input(this.sample());for(let id of ['conv-photo','feature-input','probe-before'])this.drawRGB(id,x);this.drawRGB('probe-after',this.transformed());
  if(this.id===17)this.drawKernel(x);
  if(this.id===18){let f=this.net.forward(x);for(let c=0;c<8;c++){let can=$('#feature-'+c);if(!can)continue;let ctx=can.getContext('2d'),max=Math.max(...Array.from({length:121},(_,i)=>f.a[i*8+c]),.001);for(let i=0;i<121;i++){let val=f.a[i*8+c]/max;ctx.fillStyle=`rgb(${Math.round(20+220*val)},${Math.round(28+135*val)},${Math.round(32+65*val)})`;ctx.fillRect(i%11*8,Math.floor(i/11)*8,8,8)}}let can=$('#loss-chart');if(can){let c=can.getContext('2d'),h=this.saved.history;c.fillStyle='#101820';c.fillRect(0,0,640,220);c.strokeStyle='#35424d';c.beginPath();c.moveTo(40,15);c.lineTo(40,190);c.lineTo(620,190);c.stroke();c.fillStyle='#9faeb9';c.font='12px sans-serif';c.fillText('TRAINING LOSS',48,26);if(h.length){let max=Math.max(...h.map(a=>a.loss),.01);c.strokeStyle='#ff873b';c.lineWidth=2;c.beginPath();h.forEach((a,i)=>{let px=45+i*565/Math.max(1,h.length-1),py=180-a.loss/max*130;if(i)c.lineTo(px,py);else c.moveTo(px,py)});c.stroke();c.fillText(h.at(-1).loss.toFixed(4),540,28)}else c.fillText('Start training to record actual loss.',100,110)}}
 },
 drawKernel(x){let k=this.kernel==='vertical'?[-1,0,1,-1,0,1,-1,0,1]:this.kernel==='horizontal'?[-1,-1,-1,0,0,0,1,1,1]:Array(9).fill(1/9),gray=Array.from({length:576},(_,i)=>(x[i*3]+x[i*3+1]+x[i*3+2]+3)/6),out=[];for(let y=1;y<23;y++)for(let col=1;col<23;col++){let v=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)v+=gray[(y+dy)*24+col+dx]*k[(dy+1)*3+dx+1];out.push(v)}let can=$('#conv-map');if(can){let ctx=can.getContext('2d'),max=Math.max(...out.map(Math.abs),.001),scale=288/22;out.forEach((v,i)=>{let n=Math.round(Math.abs(v)/max*255);ctx.fillStyle=`rgb(${n},${n},${n})`;ctx.fillRect(i%22*scale,Math.floor(i/22)*scale,scale+.3,scale+.3)});ctx.strokeStyle='#ff873b';ctx.lineWidth=2;ctx.strokeRect((this.scanX-1)*scale,(this.scanY-1)*scale,scale,scale)}can=$('#conv-photo');if(can){let c=can.getContext('2d');c.strokeStyle='#ff873b';c.lineWidth=3;c.strokeRect((this.scanX-1)*12,(this.scanY-1)*12,36,36)}let val=$('#kernel-number');if(val)val.textContent=`窗口中心 (${this.scanX}, ${this.scanY}) · 实际卷积响应 ${out[(this.scanY-1)*22+this.scanX-1].toFixed(4)} · 输出 22×22`},
 bindScan(){let can=$('#conv-photo');if(!can)return;let active=false,move=e=>{let b=can.getBoundingClientRect();this.scanX=Math.max(1,Math.min(22,Math.floor((e.clientX-b.left)/b.width*24)));this.scanY=Math.max(1,Math.min(22,Math.floor((e.clientY-b.top)/b.height*24)));this.scanned.add(this.kernel);this.drawImages();this.updateComplete()};can.addEventListener('pointerdown',e=>{active=true;can.setPointerCapture?.(e.pointerId);move(e)});can.addEventListener('pointermove',e=>{if(active)move(e)});can.addEventListener('pointerup',()=>active=false);can.addEventListener('pointercancel',()=>active=false)},
 review(id){let r=this.finalResult.items.find(a=>a.id===id),s=this.data.samples.find(a=>a.id===id);modal('审阅一张观测',`<img class="review-image" src="${this.image(s)}" alt="待核查卫星影像"><div class="record-pair"><div>模型预测<strong>${this.names[r.pred]}</strong></div><div>参考标签<strong>${this.names[r.actual]}</strong></div></div><p>${r.pred===r.actual?'这次预测正确。仍要结合其他图像判断整体表现。':'这次预测错误。检查画面中的纹理、混合地物与分辨率；如果据此调整模型，需要新的独立评估集。'}</p>`)}
};
